parameters.jsonBody:
={
  "model": "deepseek-chat",
  "response_format": {
    "type": "json_object"
  },
  "messages": [
    {
      "role": "system",
      "content": "You are an expert Tier 1 SOC Analyst AI for Project Heimdall. Your task is to analyze security alerts from Wazuh and threat intelligence from VirusTotal. You must output your response in valid JSON format. \n\nYour JSON output must include:\n1. 'severity': (Critical, High, Medium, Low)\n2. 'threat_summary': A concise, one-paragraph explanation of what occurred.\n3. 'mitre_tactic': The associated MITRE ATT&CK tactic (if applicable).\n4. 'vt_summary': A string summarizing the VirusTotal engine detection ratios. If VirusTotal indicates malicious hits (>0), explicitly mention this ratio here and elevate the alert severity. If no external intelligence is available, state 'N/A'.\n5. 'recommended_action': Specific, immediate steps for the human analyst.\n\nRely on the Wazuh log data as the primary source of truth, enriched by the VirusTotal stats."
    },
    {
      "role": "user",
      "content": {{ JSON.stringify("Please analyze the following event data:\n\nWAZUH ALERT:\n" + JSON.stringify($('Webhook (from wazuh)').first().json.body) + "\n\nVIRUSTOTAL STATISTICS:\n" + ($('VirusTotal Hash Check').isExecuted ? JSON.stringify($('VirusTotal Hash Check').first().json.data.attributes.last_analysis_stats) : ($('VirusTotal IP check').isExecuted ? JSON.stringify($('VirusTotal IP check').first().json.data.attributes.last_analysis_stats) : "No external intelligence available."))) }}
    }
  ]
}

={{
  {
    "channel": "C0BALTHCD6J",
    "text": "🚨 New Heimdall Alert: " + ($json.ai_output?.severity || "Unknown") + " Severity",
    "blocks": [
      {
        "type": "header",
        "text": {
          "type": "plain_text",
          "text": "🛡️ Heimdall Security Alert",
          "emoji": true
        }
      },
      {
        "type": "divider"
      },
      {
        "type": "section",
        "fields": [
          {
            "type": "mrkdwn",
            "text": "*🔴 Severity:*\n" + ($json.ai_output?.severity || "Unknown")
          },
          {
            "type": "mrkdwn",
            "text": "*🕒 Time:*\n" + ($json.wazuh_data?.timestamp || "Unknown")
          },
          {
            "type": "mrkdwn",
            "text": "*🎯 MITRE Tactic:*\n" + ($json.ai_output?.mitre_tactic || "Unknown").split(' - ')[0]
          },
          {
            "type": "mrkdwn",
            "text": "*🌐 Source IP:*\n" + ($json.wazuh_data?.all_fields?.data?.srcip || "N/A")
          },
          {
            "type": "mrkdwn",
            "text": "*💻 Host:*\n" + ($json.wazuh_data?.all_fields?.agent?.name || "Ubuntu-Agent-Test")
          }
        ]
      },
      {
        "type": "section",
        "text": {
          "type": "mrkdwn",
          "text": "*📝 Alert Summary:*\n" + ($json.ai_output?.threat_summary || "No summary provided.")
        }
      },
      {
        "type": "section",
        "text": {
          "type": "mrkdwn",
          "text": "*🔬 VirusTotal Intelligence:*\n" + ($json.ai_output?.vt_summary || "N/A")
        }
      },
      {
        "type": "section",
        "text": {
          "type": "mrkdwn",
          "text": "*🛠️ Recommended Actions:*\n" + ($json.ai_output?.recommended_action || "Investigate manually.")
        }
      },
      {
        "type": "divider"
      },
      {
        "type": "context",
        "elements": [
          {
            "type": "mrkdwn",
            "text": "📜 *Raw Rule:* " + ($json.wazuh_data?.title || "N/A") + " | *Level:* " + ($json.wazuh_data?.severity || "0") + "/15 | *ID:* " + ($json.wazuh_data?.rule_id || "N/A")
          }
        ]
      },
      {
        "type": "actions",
        "elements": [
          {
            "type": "button",
            "text": {
              "type": "plain_text",
              "text": "🔍 View in Wazuh",
              "emoji": true
            },
            "url": "https://localhost/app/wazuh#/alerts?id=" + ($json.wazuh_data?.id || ""),
            "style": "primary"
          },
          {
            "type": "button",
            "text": {
              "type": "plain_text",
              "text": "✅ Acknowledge",
              "emoji": true
            },
            "action_id": "acknowledge"
          },
          {
            "type": "button",
            "text": {
              "type": "plain_text",
              "text": "❌ False Positive",
              "emoji": true
            },
            "style": "danger",
            "action_id": "false_positive"
          }
        ]
      }
    ]
  }
}}

={{
  {
    "channel": $json.parsed_payload.container.channel_id,
    "ts": $json.parsed_payload.container.message_ts,
    "text": "✅ Alert Acknowledged",
    "blocks": [
      {
        "type": "header",
        "text": {
          "type": "plain_text",
          "text": "🛡️ Heimdall Security Alert",
          "emoji": true
        }
      },
      {
        "type": "section",
        "text": {
          "type": "mrkdwn",
          "text": "✅ *This incident has been acknowledged and is currently under investigation.*"
        }
      },
      {
        "type": "context",
        "elements": [
          {
            "type": "mrkdwn",
            "text": "Triage handled by: <@" + $json.parsed_payload.user.id + ">"
          }
        ]
      }
    ]
  }
}}

={{
  {
    "channel": $json.parsed_payload.container.channel_id,
    "ts": $json.parsed_payload.container.message_ts,
    "text": "🚫 Alert marked as False Positive",
    "blocks": [
      {
        "type": "header",
        "text": {
          "type": "plain_text",
          "text": "🛡️ Heimdall Security Alert",
          "emoji": true
        }
      },
      {
        "type": "section",
        "text": {
          "type": "mrkdwn",
          "text": "🚫 *This incident has been closed out and marked as a False Positive.*"
        }
      },
      {
        "type": "context",
        "elements": [
          {
            "type": "mrkdwn",
            "text": "Closed by: <@" + $json.parsed_payload.user.id + ">"
          }
        ]
      }
    ]
  }
}}
